@php
    $chartLabel = ['visitors' => 'visitantes', 'views' => 'páginas vistas', 'tracking' => 'búsquedas de paquetes'][$filters['chart_metric']];
    $maxTrend = max(1, (int) $trendSeries->max('total'), (int) $comparisonTrendSeries->max('total'));
    $formatDelta = fn ($delta) => $delta['value'] === null ? 'Sin base de comparación' : ($delta['direction'] === 'up' ? '+' : ($delta['direction'] === 'down' ? '−' : '')) . number_format($delta['value'], 1) . '% vs. comparación';
    $metrics = [
        ['Visitantes únicos', $summary['visitors_in_range'], 'Visitantes diferentes en el período', $summary['visitors_delta']],
        ['Páginas vistas', $summary['page_views_in_range'], 'Total de visitas a páginas', $summary['page_views_delta']],
        ['Búsquedas de envíos', $summary['tracking_searches_in_range'], 'Consultas de seguimiento', $summary['tracking_delta']],
        ['Interacciones', $summary['interactions_in_range'], 'Clics, búsquedas y cotizaciones', null],
    ];
    $makePoints = function ($series) use ($maxTrend) {
        return $series->values()->map(fn ($point, $i) => (20 + ($series->count() === 1 ? 380 : $i / ($series->count() - 1) * 760)) . ',' . (200 - $point->total / $maxTrend * 175))->implode(' ');
    };
@endphp
